structure.mermaidSource:
flowchart TD
  start["Início: Verbo HAVER na oração"] --> dec_sentido{"Qual é o valor semântico do HAVER original?"}
  dec_sentido -- "Tempo decorrido" --> dec_subst_tempo{"O substituto proposto é FAZER?"}
  dec_subst_tempo -- "Não" --> res_tempo_invalido["Rejeitar reescrita: tempo decorrido exige verbo FAZER"]
  dec_subst_tempo -- "Sim" --> dec_conc_fazer{"O verbo FAZER foi mantido no singular?"}
  dec_conc_fazer -- "Sim" --> res_fazer_ok["Reescrita CORRETA: FAZER temporal é impessoal"]
  dec_conc_fazer -- "Não (flexionou no plural)" --> res_fazer_erro["Reescrita INCORRETA: FAZER temporal não vai ao plural"]
  dec_sentido -- "Acontecimento / Evento" --> dec_subst_evento{"Qual verbo foi proposto pela banca?"}
  dec_subst_evento -- "Existir" --> res_evento_invalido["Rejeitar reescrita: Quebra semântica (evento não equivale a existir)"]
  dec_subst_evento -- "Ocorrer / Acontecer" --> dec_conc_evento{"O novo sujeito (antigo OD) está no plural?"}
  dec_conc_evento -- "Sim" --> res_evento_pl["Reescrita CORRETA: Flexionar no plural (ex.: Ocorreram erros)"]
  dec_conc_evento -- "Não" --> res_evento_sg["Reescrita CORRETA: Manter no singular (ex.: Ocorreu um erro)"]
  dec_sentido -- "Existência" --> dec_subst_exist{"O substituto proposto é EXISTIR?"}
  dec_subst_exist -- "Não" --> res_exist_invalido["Rejeitar reescrita: Verbo proposto inadequado ao sentido de existência"]
  dec_subst_exist -- "Sim" --> dec_conc_exist{"O novo sujeito (antigo OD) está no plural?"}
  dec_conc_exist -- "Sim" --> res_exist_pl["Reescrita CORRETA: Flexionar no plural (ex.: Existiam dúvidas)"]
  dec_conc_exist -- "Não" --> res_exist_sg["Reescrita CORRETA: Manter no singular (ex.: Existia uma dúvida)"]

flowchart TD
  start(["Início: Forma Verbal em Análise"]) --> dec_impes{"Passo 1: Verbo impessoal? (Fenômeno natural, haver ou fazer temporal)"}
  dec_impes -- "Sim" --> res_inexistente["Oração Sem Sujeito (Sujeito Inexistente)"]
  dec_impes -- "Não" --> dec_desinencia{"Passo 2: Análise da flexão / desinência verbal"}
  dec_desinencia -- "1ª Pessoa (Eu / Nós)" --> res_oculto_1p["Sujeito Oculto / Desinencial"]
  dec_desinencia -- "3ª Pessoa Singular (Ele / Ela)" --> dec_se_indet{"Possui partícula 'se' de indeterminação?"}
  dec_se_indet -- "Sim" --> res_indet_se["Sujeito Indeterminado"]
  dec_se_indet -- "Não" --> res_oculto_3s["Sujeito Oculto / Elíptico Contextual"]
  dec_desinencia -- "3ª Pessoa Plural (Eles / Elas)" --> dec_ref_3p{"Há referente expresso no contexto anterior?"}
  dec_ref_3p -- "Sim" --> res_oculto_3p["Sujeito Oculto / Elíptico Contextual"]
  dec_ref_3p -- "Não" --> res_indet_3p["Sujeito Indeterminado"]
